def splitArray(nums: list[int], k: int) -> int:
    lo, hi = max(nums), sum(nums)
    ans = hi
    while lo <= hi:
        mid = (lo + hi) // 2
        splits = 1
        curr = 0
        for x in nums:
            if curr + x > mid:
                splits += 1
                curr = x
            else:
                curr += x
        if splits <= k:
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return ans

